export interface DetailedSubjectGrade {
  id: string;
  code: string;
  name: string;
  teacher: string;
  teacherEmail: string;
  weeklyHours: number;
  category: "Plan Común" | "Especialidad TP";
  room: string;
  grades: {
    code: string;
    label: string;
    weightPct: number;
    value: number | null;
    date: string;
    feedback?: string;
  }[];
  currentAvg: number;
  attendanceRate: number;
  status: "Aprobando" | "Destacado" | "En Riesgo";
}

export interface StudentAcademicRecord {
  num: number;
  fullName: string;
  firstName: string;
  lastName: string;
  email: string;
  rut: string;
  courseName: string;
  courseCode: string;
  grade: number;
  letter: string;
  specialty: string;
  overallGpa: number;
  overallAttendance: number;
  subjects: DetailedSubjectGrade[];
}

