export function getStudentAcademicRecord(identifier: string): StudentAcademicRecord | null {
  if (!identifier) return null;
  const clean = identifier.trim().toLowerCase();
  
  // Alias específico para Joaquín Pérez De Arce
  if (clean === "joaquin.perez@lpmm.cl") {
    return LPMM_STUDENTS_ACADEMIC_RECORDS["arce.perez@lpmm.cl"] || null;
  }

  if (LPMM_STUDENTS_ACADEMIC_RECORDS[clean]) {
    return LPMM_STUDENTS_ACADEMIC_RECORDS[clean];
  }
  
  // Búsqueda por RUN/RUT
  if (LPMM_STUDENTS_ACADEMIC_RECORDS[identifier.trim()]) {
    return LPMM_STUDENTS_ACADEMIC_RECORDS[identifier.trim()];
  }
  
  // Búsqueda exacta por correo en todos los registros
  for (const record of Object.values(LPMM_STUDENTS_ACADEMIC_RECORDS)) {
    if (record && record.email && record.email.toLowerCase() === clean) {
      return record;
    }
  }

  // Normalización sin acentos para coincidencia robusta por nombre
  const norm = (str: string) =>
    str.normalize("NFD").replace(/[\u0300-\u036f]/g, "").toLowerCase();
  const cleanNorm = norm(clean);

  for (const record of Object.values(LPMM_STUDENTS_ACADEMIC_RECORDS)) {
    if (!record) continue;
    const fullNorm = norm(record.fullName);
    const firstLastNorm = norm(`${record.firstName} ${record.lastName}`);
    const lastFirstNorm = norm(`${record.lastName} ${record.firstName}`);
    if (
      fullNorm === cleanNorm ||
      firstLastNorm === cleanNorm ||
      lastFirstNorm === cleanNorm ||
      fullNorm.includes(cleanNorm) ||
      cleanNorm.includes(fullNorm)
    ) {
      return record;
    }
  }

  // Fallback seguro a Yamir Ahumada (1° Medio A) si no existe registro
  return LPMM_STUDENTS_ACADEMIC_RECORDS["yamir.ahumada@lpmm.cl"] || null;
}

export interface StudentDirectoryItem {
  email: string;
  fullName: string;
  firstName: string;
  lastName: string;
  rut: string;
  courseName: string;
  specialty: string;
  overallGpa: number;
}

export function getAllStudentsDirectory(): StudentDirectoryItem[] {
  const map = new Map<string, StudentDirectoryItem>();
  for (const record of Object.values(LPMM_STUDENTS_ACADEMIC_RECORDS)) {
    if (record && record.email && !map.has(record.email.toLowerCase())) {
      map.set(record.email.toLowerCase(), {
        email: record.email,
        fullName: record.fullName,
        firstName: record.firstName,
        lastName: record.lastName,
        rut: record.rut,
        courseName: record.courseName,
        specialty: record.specialty,
        overallGpa: record.overallGpa,
      });
    }
  }
  return Array.from(map.values()).sort((a, b) => {
    if (a.courseName !== b.courseName) return a.courseName.localeCompare(b.courseName);
    return a.fullName.localeCompare(b.fullName);
  });
}

